import{_ as a,o as t,c as i,a3 as s}from"./chunks/framework.Ch_0qWu9.js";const k=JSON.parse('{"title":"运行环境要求","description":"","frontmatter":{"sourcePath":"docs/runtime-availability.zh-CN.md","sourceUrl":"https://github.com/MoonshotAI/TCSExam/blob/aab56977addd5d217972b7f35cf50be4440cb6c7/docs/runtime-availability.zh-CN.md","alternateUrl":"/TCSExam/docs/runtime-availability/","alternateAnchors":{"运行环境要求":"runtime-requirements","主机与题目资源":"host-and-task-resources","准备与检查":"prepare-and-check","验证与结果":"verification-and-results","runtime-requirements":"runtime-requirements","host-and-task-resources":"host-and-task-resources","prepare-and-check":"prepare-and-check","verification-and-results":"verification-and-results"}},"headers":[],"relativePath":"zh/runtime-availability/index.md","filePath":"zh/runtime-availability/index.md"}'),r={name:"zh/runtime-availability/index.md"};function n(o,e,d,c,l,h){return t(),i("div",null,[...e[0]||(e[0]=[s(`<p><a id="runtime-requirements"></a></p><h1 id="运行环境要求" tabindex="-1">运行环境要求 <a class="header-anchor" href="#运行环境要求" aria-label="Permalink to &quot;运行环境要求&quot;">​</a></h1><p>本参考文档介绍运行 TCSExam 所需的主机和镜像条件。 面向配置评测主机资源或准备判分服务的用户。</p><p><a id="host-and-task-resources"></a></p><h2 id="主机与题目资源" tabindex="-1">主机与题目资源 <a class="header-anchor" href="#主机与题目资源" aria-label="Permalink to &quot;主机与题目资源&quot;">​</a></h2><p>在 Linux x86-64 上运行，使用 Python 3.12+、Docker Engine、Compose 和 Buildx。 使用评测用户可以访问的本地 Docker Unix socket。CLI 和 Docker 必须使用相同的 题目与任务输出路径；不接受远程 SSH/TCP Docker context。安装检查见 <a href="/TCSExam/docs/zh/running/#install-and-select">运行评测</a>。</p><p>每道 Lean 题申请 4 个 CPU 核和 16 GiB 内存。为操作系统和构建预留额外资源， 并为共享 Lean 环境、镜像层和日志预留至少 40 GB 磁盘。这部分磁盘空间涵盖共享 环境；Full 构建还需要存放所选数据集和镜像。</p><p>Solver 资源要求因题目和数据划分而异。请查看题目的 <code>task.toml</code>，以及控制器或 后端规划器生成的资源计划。主机必须能够同时容纳开发容器、控制器预留资源， 以及至少一个获得题目规定的完整单实例资源的 worker。降低题目并发数无法减小 单个 worker 的资源需求。实例调度保留每个实例的计算资源和时间配额；共享时间池 题将完整时间池保留在同一个 worker 中。见 <a href="/TCSExam/docs/zh/offline-adapters/">Offline 资源规则</a> 和 <a href="/TCSExam/docs/zh/backend/docker/#resources-and-lifecycle">Online 后端资源</a>。</p><p>读法说明：按题目组查看。镜像角色说明所选题目需要准备哪些镜像。</p><table tabindex="0"><thead><tr><th>题目组</th><th>镜像角色</th><th>额外执行要求</th></tr></thead><tbody><tr><td>定理证明、构造和开放猜想</td><td>开发环境和独立判分器</td><td>Harbor 支持镜像及题目声明的资源</td></tr><tr><td>Offline Solver</td><td>开发环境、判分控制器和判分 worker</td><td>控制器可访问 Docker socket，并以只读方式查看 cgroup</td></tr><tr><td>Online Solver</td><td>开发环境和后端判分 worker</td><td>运行中的后端、服务凭据，以及开发容器和判分容器均可访问的地址</td></tr></tbody></table><p>两种 Solver 方式都要求启用 Landlock ABI 3 或以上版本、允许 Landlock 系统调用， 并在判分容器中以 root 身份进行监督管理。构建和求解器命令以受限权限运行。 <a href="/TCSExam/docs/zh/judge-execution-isolation/">隔离预检查</a>在执行主机上检查实际准备的镜像。 如果检查失败，应修正主机策略或换用受支持的主机，然后再开始评测。</p><p><a id="prepare-and-check"></a></p><h2 id="准备与检查" tabindex="-1">准备与检查 <a class="header-anchor" href="#准备与检查" aria-label="Permalink to &quot;准备与检查&quot;">​</a></h2><p>对于默认的 Lite 选择：</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">tcsexam</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> source-inputs</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">tcsexam</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> build</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --suite</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> lite</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">tcsexam</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> doctor</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --suite</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> lite</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --output</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> build/lite-readiness.json</span></span></code></pre></div><p><code>build</code> 准备题目镜像和配套的 Harbor 主机支持镜像。固定输入及其获取命令见 <a href="/TCSExam/docs/zh/resources/">资源准备</a>。对于外部准备的镜像，通过 <code>--artifacts</code> 提供完整清单； 其中的记录必须标明实际镜像和 Harbor 支持产物。</p><p><code>doctor</code> 在 JSON 报告中写入所选题目的前置条件和 <code>blockers</code>。 在执行 <code>run</code> 前解决这些问题。agent 检查核验配置和本地凭据是否存在，不会连接 模型服务。Online 服务配置与连通性检查见 <a href="/TCSExam/docs/zh/backend/docker/#check-and-start">后端指南</a>。</p><p><a id="verification-and-results"></a></p><h2 id="验证与结果" tabindex="-1">验证与结果 <a class="header-anchor" href="#验证与结果" aria-label="Permalink to &quot;验证与结果&quot;">​</a></h2><p>Lean 判分器使用固定的项目和依赖配置。定理证明题和构造题接受 <code>Task/Basic.lean</code>；开放猜想题还接受各题文档说明的额外 Lean 源文件。 提交中的构建配置、依赖目录、编译文件和评分脚本会被忽略。 提交源码路径中的符号链接会被拒绝。</p><p>最终 Lean 源码必须使用普通定义和证明。所有提交源文件中，运行自定义元程序 或改变 elaboration 过程的命令都会被拒绝，例如 <code>run_cmd</code>、<code>run_tac</code>、<code>elab</code>、 <code>macro</code>、<code>initialize</code> 和 <code>#eval</code>。判分器检查公理的完全限定名。 构造题保留题目文档说明的 <code>native_decide</code> 支持；在接受之前，会通过求值检查其 生成的布尔等式。开放猜想题若提交同时通过猜想及其否定的检查，得分为零。</p><p>Solver 隐藏输入只提供给判分环境。模型开发容器既没有这些输入，也没有 Docker socket。Online 归档凭据仅供最终验证使用；见 <a href="/TCSExam/docs/zh/running/#online-solver">运行 Online Solver</a>。</p><p>成功执行的评分器会输出有限数值的 Harbor 奖励。<code>score-details.json</code> 或 <code>judge_result.json</code> 等题目详细报告说明结果。判分失败时，应先检查判分器日志和 异常，再确定分数。通过<a href="/TCSExam/docs/zh/running/#keep-outputs-and-statuses">结果检查</a>定位这些 文件，并将已完成判分的零分与执行失败分开记录。</p>`,23)])])}const u=a(r,[["render",n]]);export{k as __pageData,u as default};
